import{V as e,ht as t,nt as n,tt as r}from"./chunks/framework.CfX5xiXd.js";var i=JSON.parse(`{"title":"Guides","description":"","frontmatter":{},"headers":[],"relativePath":"guides/index.md","filePath":"guides/index.md","lastUpdated":0}`),a={name:`guides/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="guides" tabindex="-1">Guides <a class="header-anchor" href="#guides" aria-label="Permalink to “Guides”">​</a></h1><p>MangaReader content extensions are small, separately reviewed integrations. The repository does not host comics, and an extension does not become trusted merely because it appears in a catalog. Tracker and theme extension kinds are not supported.</p><h2 id="review-an-extension" tabindex="-1">Review an extension <a class="header-anchor" href="#review-an-extension" aria-label="Permalink to “Review an extension”">​</a></h2><p>Before opening an install link, check these fields in the <a href="/extensions/extension-list">Extension List</a>:</p><ol><li><strong>Availability</strong> — <code>Service unavailable</code> identifies a known runtime blocker; <code>Available</code> means the declared compatibility surface can proceed to MangaReader review.</li><li><strong>Permissions</strong> — compare requested access with the extension&#39;s stated purpose.</li><li><strong>Allowed HTTPS hosts</strong> — network access should be narrow and recognizable.</li><li><strong>Rights and provenance</strong> — inspect the source license, package notice, and service-rights record.</li><li><strong>Package hash</strong> — MangaReader uses the published SHA-256 value to detect changed artifacts.</li><li><strong>Repository</strong> — custom catalogs have different maintainers and review processes.</li></ol><div class="tip custom-block"><p class="custom-block-title">Start small</p><p>Install only the integrations you intend to use. A smaller extension set is easier to review, troubleshoot, and keep current.</p></div><h2 id="custom-catalogs" tabindex="-1">Custom catalogs <a class="header-anchor" href="#custom-catalogs" aria-label="Permalink to “Custom catalogs”">​</a></h2><p>The catalog browser accepts either a full <code>catalog.json</code> URL or the directory containing it. A compatible catalog must:</p><ul><li>be served over HTTP or HTTPS without embedded credentials;</li><li>expose a JSON object with a <code>sources</code> array;</li><li>give every source a unique, non-empty <code>id</code>;</li><li>contain only content extensions (<code>kind: &quot;content&quot;</code>, or an omitted kind that defaults to content);</li><li>publish package and icon paths relative to its repository URL; and</li><li>permit browser access with appropriate cross-origin response headers.</li></ul><p>Custom catalog URLs are saved in local browser storage. They are never synchronized to an account because this website has no sign-in or backend. Shared catalog links include the custom URLs required to reproduce the view.</p><p>To remove a custom catalog, open <strong>Repositories</strong> on the Extension List and select the × button next to it.</p><h2 id="content-ratings" tabindex="-1">Content ratings <a class="header-anchor" href="#content-ratings" aria-label="Permalink to “Content ratings”">​</a></h2><table tabindex="0"><thead><tr><th>Rating</th><th>Intended use</th></tr></thead><tbody><tr><td>Safe</td><td>General-audience catalog metadata.</td></tr><tr><td>Mature</td><td>Material that may include stronger themes or imagery.</td></tr><tr><td>Adult</td><td>Explicit material intended only for adults where lawful.</td></tr><tr><td>Unknown</td><td>The publisher did not provide a recognized rating. Treat it cautiously.</td></tr></tbody></table><p>The Extension List begins with <strong>Safe</strong> included when opened without a shared state. Click a filter once to include it, twice to exclude it, and a third time to clear it. Clearing all rating filters shows every rating.</p><h2 id="troubleshooting-catalogs" tabindex="-1">Troubleshooting catalogs <a class="header-anchor" href="#troubleshooting-catalogs" aria-label="Permalink to “Troubleshooting catalogs”">​</a></h2><p>If a custom catalog does not load:</p><ul><li>confirm that its address resolves to <code>catalog.json</code>;</li><li>open the JSON address directly and check for an HTTP error;</li><li>make sure the catalog server allows cross-origin browser requests;</li><li>check that <code>sources</code> is an array with no duplicate IDs; and</li><li>remove credentials, fragments, and unrelated JSON filenames from the URL.</li></ul>`,17)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};